"use strict";

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { browserType } = require('./qa-browser.cjs');
const base = process.env.XIANGQI_QA_URL || 'http://127.0.0.1:5200/web-xiangqi/';
const readyTimeout = Number(process.env.XIANGQI_QA_READY_TIMEOUT_MS || 60000);
// Publication tests check these exact generated bytes. Serve that wrapper
// with the real shipped scalar cores, rejecting every obsolete SIMD request.
const wrapper = fs.readFileSync(process.env.XIANGQI_QA_WRAPPER_PATH || path.join(__dirname, '../templates/pikafish.js'), 'utf8')
  .replace('const BUILD_HAS_SIMD = true;', 'const BUILD_HAS_SIMD = false;');

(async () => {
  const browser = await browserType.launch();
  try {
    for (const width of [1440, 390]) {
      const context = await browser.newContext({ viewport: { width, height: 900 }, serviceWorkers: 'block' });
      try {
        const simdRequests = [];
        await context.route('**/pikafish-core*-simd.*', route => {
          simdRequests.push(route.request().url());
          return route.abort();
        });
        await context.route('**/pikafish.js', async route => {
          // Preserve isolation headers on the dedicated-worker response.
          const response = await route.fetch();
          return route.fulfill({ response, contentType: 'application/javascript', body: wrapper });
        });
        const page = await context.newPage();
        const errors = [];
        page.on('pageerror', error => errors.push(error.message));
        await page.goto(base);
        if (width < 900) {
          await page.getByTestId('mobile-view-analysis').click();
          await page.getByTestId('mobile-analysis-tab-engine').click();
        } else await page.locator('button:visible', { hasText: /^Engine$/ }).first().click();
        // The header status is hidden at phone widths; its ready marker still
        // reflects the handshake, while the visible dashboard is checked below.
        await page.locator('.top-engine-state .status-dot.healthy').waitFor({ state: 'attached', timeout: readyTimeout })
          .catch(error => { throw new Error(`Scalar build did not become ready; SIMD requests: ${JSON.stringify(simdRequests)}; page errors: ${JSON.stringify(errors)}`, { cause: error }); });
        assert.deepEqual(simdRequests, [], 'A scalar-only build requested an unavailable SIMD core');
        const dashboard = page.locator('.engine-dashboard');
        await dashboard.waitFor();
        const text = await dashboard.innerText();
        assert.match(text, /threaded|single/);
        assert.doesNotMatch(text, /threaded-simd|single-simd/);
        await page.screenshot({ path: `/tmp/xiangqi-scalar-build-${browserType.name()}-${width}.png` });

        if (width === 1440) {
          const { searches, supportsThreads } = await page.evaluate(async basePath => {
            const factory = window.Pikafish;
            if (!factory.wasmSIMDSupported()) throw new Error('This regression needs a SIMD-capable browser');
            const results = [];
            for (const variant of ['single-simd', 'threaded-simd']) {
              const engine = await factory.createWorkerEngine({ basePath, variant, allowSIMD: true, threads: 1, hashMB: 16 });
              try {
                const result = await new Promise((resolve, reject) => {
                  let depth = 0;
                  const timer = setTimeout(() => reject(new Error('Scalar search timed out')), 20000);
                  const listener = line => {
                    const match = line.match(/^info .*\bdepth (\d+)/);
                    if (match) depth = Math.max(depth, Number(match[1]));
                    if (line.startsWith('bestmove ')) {
                      clearTimeout(timer); engine.removeMessageListener(listener);
                      resolve({ requested: variant, resolved: engine.variant, depth, bestmove: line });
                    }
                  };
                  engine.addMessageListener(listener);
                  engine.postMessage('position startpos'); engine.postMessage('go depth 3');
                });
                results.push(result);
              } finally { await engine.terminate(); }
            }
            return { searches: results, supportsThreads: factory.wasmThreadsSupported() };
          }, base);
          assert.deepEqual(searches.map(result => result.resolved), ['single', supportsThreads ? 'threaded' : 'single']);
          for (const result of searches) {
            assert.ok(result.depth >= 3, JSON.stringify(result));
            assert.match(result.bestmove, /^bestmove [a-i][0-9][a-i][0-9]/);
          }
          console.log(browserType.name(), searches);
        }
        assert.deepEqual(simdRequests, []);
        assert.deepEqual(errors, []);
        console.log(`${browserType.name()} ${width}px: scalar-only app ready, runtime label correct, no SIMD requests`);
      } finally { await context.close(); }
    }
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
